class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors) {
        int n = colors.size(), ans = 0;
        vector<int> b(colors.begin(), colors.end());
        b.push_back(colors[0]); b.push_back(colors[1]);
        for (int i = 0; i < n; i++)
            if (b[i] != b[i + 1] && b[i + 1] != b[i + 2]) ans++;
        return ans;
    }
};

