class Solution {
    public int numberOfAlternatingGroups(int[] colors) {
        int n = colors.length, ans = 0;
        int[] b = new int[n + 2];
        System.arraycopy(colors, 0, b, 0, n);
        b[n] = colors[0]; b[n + 1] = colors[1];
        for (int i = 0; i < n; i++)
            if (b[i] != b[i + 1] && b[i + 1] != b[i + 2]) ans++;
        return ans;
    }
}

